import * as THREE from './three.module.js';

// Everything in this scene is generated by code: curved shell meshes, growth lines,
// nacre, pearl, steel blade and wood handle. The lid rotates about a fixed hinge.
const stage=document.querySelector('#stage');
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(stage.clientWidth,stage.clientHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.55;
stage.appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color('#f1ead8');
const camera=new THREE.OrthographicCamera(-6.6,6.6,3.7125,-3.7125,.1,100);
camera.position.set(0,0,18);camera.lookAt(0,0,0);
scene.add(new THREE.AmbientLight('#fff8e5',.72));
const key=new THREE.DirectionalLight('#fff0d6',2.45);key.position.set(-3,5,10);scene.add(key);
const fill=new THREE.DirectionalLight('#d6e7ed',.43);fill.position.set(5,-2,7);scene.add(fill);
const MAT=(color,opts={})=>new THREE.MeshStandardMaterial({color,roughness:.77,...opts});
const INK='#463322', GOLD='#b68b53';
function add(parent,geo,material,x=0,y=0,z=0){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);parent.add(o);return o;}
function tube(parent,pts,color=INK,r=.023){const curve=new THREE.CatmullRomCurve3(pts.map(p=>new THREE.Vector3(...p)));return add(parent,new THREE.TubeGeometry(curve,Math.max(24,pts.length*6),r,7,false),MAT(color,{roughness:.91}));}
function dot(parent,x,y,z,r,color=INK){return add(parent,new THREE.SphereGeometry(r,18,12),MAT(color,{roughness:.45}),x,y,z);}
function seeded(x,y,k=0){let n=Math.sin(x*127.1+y*311.7+k*74.7)*43758.5453;return n-Math.floor(n);}
function ellipsoid(parent,x,y,z,sx,sy,sz,material){const o=add(parent,new THREE.SphereGeometry(1,40,28),material,x,y,z);o.scale.set(sx,sy,sz);return o;}

// Fine paper texture, made at runtime.
const paper=document.createElement('canvas');paper.width=512;paper.height=512;
const pc=paper.getContext('2d');pc.fillStyle='#f3ecd9';pc.fillRect(0,0,512,512);
for(let i=0;i<33000;i++){const x=seeded(i,2)*512,y=seeded(i,3)*512;pc.fillStyle=i%3?'#b9aa8340':'#ffffff50';pc.fillRect(x,y,1+seeded(i,4)*1.5,1+seeded(i,5)*1.5);}
const tex=new THREE.CanvasTexture(paper);tex.colorSpace=THREE.SRGBColorSpace;
add(scene,new THREE.PlaneGeometry(13.2,7.425),new THREE.MeshBasicMaterial({map:tex}),0,0,-2.4);
const shadow=ellipsoid(scene,-2,-1.80,-1.7,2.65,.31,.01,new THREE.MeshBasicMaterial({color:'#7b614b',transparent:true,opacity:.13,depthWrite:false}));

const clam=new THREE.Group();clam.position.set(-2,-.45,0);scene.add(clam);
const RX=2.28, RY=1.37;
function shellMesh(sign,inner=false){
  const nx=84,nv=25,pos=[],col=[],idx=[];
  for(let i=0;i<=nx;i++){
    const u=-.999+1.998*i/nx,arc=Math.sqrt(1-u*u);
    for(let j=0;j<=nv;j++){
      const v=j/nv;
      const x=u*RX,y=sign*RY*arc*v;
      const bulge=Math.sin(Math.PI*v)*arc;
      const z=inner?.80+.18*bulge:.16+.48*bulge;
      pos.push(x,y,z);
      const noise=(seeded(i,j,inner?9:1)-.5)*.13;
      const rings=.055*Math.sin(24*v+3*u)+.025*Math.sin(51*v);
      const c=new THREE.Color(inner?'#ead0b5':'#caa773');
      if(inner){c.lerp(new THREE.Color('#e9ab96'),.48+.12*Math.sin(5*u));c.offsetHSL(0,0,noise*.42);}
      else {c.offsetHSL(.012*rings,-.05*rings,noise+rings+.09*(1-v));}
      col.push(c.r,c.g,c.b);
    }
  }
  for(let i=0;i<nx;i++)for(let j=0;j<nv;j++){
    const a=i*(nv+1)+j,b=(i+1)*(nv+1)+j;
    idx.push(a,b,a+1,b,b+1,a+1);
  }
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.setIndex(idx);g.computeVertexNormals();
  return new THREE.Mesh(g,new THREE.MeshPhysicalMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:inner?.36:.88,metalness:inner?.08:0,clearcoat:inner?.55:0,clearcoatRoughness:.22}));
}
function shellRim(parent,sign){
  const edge=[],seam=[];
  for(let i=0;i<=76;i++){const u=-.999+1.998*i/76,x=u*RX;edge.push([x,sign*RY*Math.sqrt(1-u*u),.20]);seam.push([x,0,.22]);}
  tube(parent,edge,INK,.041);tube(parent,seam,INK,.039);
  for(let k=1;k<=6;k++){
    const v=.16+k*.105,pts=[];
    for(let i=0;i<=55;i++){const u=-.98+1.96*i/55,arc=Math.sqrt(1-u*u);pts.push([u*RX,sign*RY*arc*v,.18+.48*Math.sin(Math.PI*v)*arc+.014]);}
    tube(parent,pts,k%2?'#aa7e49':'#ddbd80',.012);
  }
}
const lower=new THREE.Group();clam.add(lower);lower.add(shellMesh(-1));shellRim(lower,-1);
const interior=new THREE.Group();lower.add(interior);interior.add(shellMesh(-1,true));
const mantle=ellipsoid(interior,0,-.54,.93,1.65,.56,.035,MAT('#dca18d',{roughness:.58,transparent:true,opacity:.69,depthWrite:false}));
const pearlHolder=new THREE.Group();pearlHolder.position.set(0,-.48,1.26);interior.add(pearlHolder);
const pearl=add(pearlHolder,new THREE.SphereGeometry(.45,48,36),new THREE.MeshPhysicalMaterial({color:'#fff3e5',metalness:.07,roughness:.055,clearcoat:1,clearcoatRoughness:.03,iridescence:1,iridescenceIOR:1.35,iridescenceThicknessRange:[100,400]}));
ellipsoid(pearlHolder,-.15,.15,.40,.115,.08,.012,new THREE.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.9}));

// The valve and its markings share this pivot. Its left edge never leaves the hinge.
const hinge=new THREE.Group();hinge.position.set(-RX,0,.18);clam.add(hinge);
const lid=new THREE.Group();lid.position.x=RX;hinge.add(lid);
lid.add(shellMesh(1));shellRim(lid,1);
// Small face keeps the character from the original illustration.
dot(lid,.13,.54,.65,.043);dot(lid,.54,.54,.62,.043);
tube(lid,[[.26,.38,.67],[.34,.34,.68],[.43,.38,.66]],INK,.019);
for(const [x,y] of [[-.03,.42],[-.12,.48],[.68,.43],[.77,.48]])dot(lid,x,y,.60,.013);
ellipsoid(clam,-RX,0,.32,.13,.11,.12,MAT('#54402e'));

// Rounded extrusions make the steel blade and wooden grip visibly thick.
const knife=new THREE.Group();scene.add(knife);
const bladeShape=new THREE.Shape();bladeShape.moveTo(-.27,-.01);bladeShape.lineTo(-.25,.73);bladeShape.quadraticCurveTo(-.18,1.32,.03,1.68);bladeShape.quadraticCurveTo(.31,1.12,.29,.69);bladeShape.lineTo(.27,-.01);bladeShape.closePath();
const blade=add(knife,new THREE.ExtrudeGeometry(bladeShape,{depth:.12,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:2,curveSegments:18}),new THREE.MeshStandardMaterial({color:'#aeb9bd',metalness:.82,roughness:.26,side:THREE.DoubleSide}),0,0,.43);
tube(knife,[[-.18,.58,.61],[-.13,1.11,.62],[.02,1.53,.62]],'#f6f7ef',.024);
const handleShape=new THREE.Shape();handleShape.moveTo(-.26,0);handleShape.lineTo(.26,0);handleShape.lineTo(.26,-.94);handleShape.quadraticCurveTo(.21,-1.12,0,-1.13);handleShape.quadraticCurveTo(-.21,-1.12,-.26,-.94);handleShape.closePath();
add(knife,new THREE.ExtrudeGeometry(handleShape,{depth:.14,bevelEnabled:true,bevelSize:.045,bevelThickness:.035,bevelSegments:3,curveSegments:14}),MAT('#9e6a3c',{roughness:.68}),0,0,.55);
for(let k=0;k<6;k++){const x=-.18+k*.063;tube(knife,[[x,-.10,.75],[x+.025,-.45,.76],[x-.01,-.86,.75]],k%2?'#b9864e':'#7e502e',.007);}
for(const y of [-.34,-.78])dot(knife,0,y,.78,.043,'#e9d1a3');
dot(knife,-.115,.23,.63,.029);dot(knife,.12,.23,.63,.029);
tube(knife,[[-.058,.12,.66],[0,.075,.67],[.061,.12,.66]],INK,.014);
tube(knife,[[-.26,-.42,.63],[-.45,-.50,.62]],INK,.038);tube(knife,[[.26,-.42,.63],[.45,-.50,.62]],INK,.038);
tube(knife,[[-.13,-1.1,.62],[-.22,-1.27,.62]],INK,.037);tube(knife,[[.13,-1.1,.62],[.22,-1.27,.62]],INK,.037);
knife.scale.setScalar(.64);
const flash=new THREE.Group();scene.add(flash);flash.position.set(.38,-.43,1);
for(const pts of [[[0,0,0],[.24,.12,0]],[[0,.05,0],[.04,.29,0]],[[-.04,-.03,0],[-.18,.11,0]]])tube(flash,pts,'#8e673b',.017);

const duration=6,smooth=x=>{x=THREE.MathUtils.clamp(x,0,1);return x*x*(3-2*x)},pulse=(t,c,w)=>Math.exp(-(((t-c)/w)**2));
function update(t){
  const approach=smooth((t-.64)/.82),away=smooth((t-2.18)/.55),contact=approach*(1-away);
  const tap=Math.max(pulse(t,1.54,.08),pulse(t,1.88,.08));
  const open=smooth((t-2.12)/1.24);
  hinge.rotation.z=.73*open;
  interior.visible=open>.025;interior.scale.y=Math.max(.025,open);pearlHolder.scale.setScalar(Math.max(.01,open));
  knife.position.set(3.20-2.86*contact,-.25+.32*contact-.13*tap,.8);
  knife.rotation.z=.33*contact+.11*tap;
  flash.visible=tap>.1;flash.scale.setScalar(.7+.45*tap);
  renderer.render(scene,camera);
}
let t=0,playing=true,last=performance.now();
const slider=document.querySelector('#timeline'),label=document.querySelector('#time'),toggle=document.querySelector('#toggle');
function display(){slider.value=t.toFixed(2);label.textContent=`${t.toFixed(1)} / 6.0 秒`;update(t);}
function tick(now){const dt=Math.min((now-last)/1000,.1);last=now;if(playing){t=(t+dt)%duration;display();}requestAnimationFrame(tick);}
toggle.onclick=()=>{playing=!playing;toggle.textContent=playing?'暂停':'播放';last=performance.now();};
document.querySelector('#restart').onclick=()=>{t=0;playing=true;toggle.textContent='暂停';display();};
slider.oninput=()=>{t=Number(slider.value);playing=false;toggle.textContent='播放';display();};
function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h);const a=w/h;camera.left=-3.7125*a;camera.right=3.7125*a;camera.updateProjectionMatrix();update(t);}
new ResizeObserver(resize).observe(stage);display();requestAnimationFrame(tick);
